sp_widget.client_script:
api.controller = function() {
    var c = this;

    c.expanded = {};

    c.toggleDetails = function(id) {
        c.expanded[id] = !c.expanded[id];
    };
};

sp_widget.css:
.my-reservations-page {
  max-width: 1050px;
  margin: 0 auto;
  padding: 55px 25px 75px;
  color: #2a2d29;
  font-family: Arial, sans-serif;
}

.reservations-heading {
  text-align: center;
  margin-bottom: 40px;
}

.reservations-eyebrow,
.empty-eyebrow {
  color: #a8875b;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 3px;
}

.reservations-heading h1 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 42px;
  margin: 12px 0;
}

.reservations-heading p {
  color: #6f756f;
  font-size: 15px;
}

.reservation-list {
  display: grid;
  gap: 22px;
}

.reservation-card {
  background: #ffffff;
  border: 1px solid #e7e1d4;
  border-radius: 12px;
  padding: 25px;
  box-shadow: 0 5px 20px rgba(31, 58, 48, 0.05);
}

.reservation-top,
.reservation-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}

.reservation-label,
.reservation-dates span {
  display: block;
  color: #a8875b;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.reservation-top h2 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 22px;
  margin: 7px 0 0;
}

.status-badge {
  background: #e8eee9;
  color: #1f3a30;
  padding: 8px 13px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
}

.reservation-room {
  display: flex;
  align-items: center;
  gap: 15px;
  margin: 25px 0;
}

.room-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  background: #e8eee9;
  color: #1f3a30;
  border-radius: 9px;
  font-size: 20px;
}

.reservation-room h3 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 20px;
  margin: 0 0 5px;
}

.reservation-room p {
  color: #6f756f;
  font-size: 12px;
  margin: 0;
}

.reservation-dates {
  display: flex;
  align-items: center;
  gap: 30px;
  padding: 20px 0;
  border-top: 1px solid #e7e1d4;
  border-bottom: 1px solid #e7e1d4;
}

.reservation-dates strong {
  display: block;
  margin-top: 9px;
  color: #2a2d29;
  font-size: 14px;
}

.date-divider {
  height: 35px;
  width: 1px;
  background: #e7e1d4;
}

.reservation-bottom {
  padding: 18px 0;
  color: #6f756f;
  font-size: 12px;
}

.reservation-bottom strong {
  color: #1f3a30;
  font-size: 18px;
}

.details-button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 13px 0 0;
  background: transparent;
  border: 0;
  border-top: 1px solid #e7e1d4;
  color: #1f3a30;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  text-align: left;
}

.reservation-details {
  margin-top: 18px;
  padding: 18px;
  background: #faf6ef;
  border-radius: 8px;
}

.reservation-details p {
  color: #6f756f;
  font-size: 13px;
  margin: 8px 0;
}

.reservation-details strong {
  color: #1f3a30;
}

.reservations-empty {
  max-width: 650px;
  margin: 35px auto 20px;
  padding: 55px 30px;
  text-align: center;
  background: #faf6ef;
  border: 1px solid #e7e1d4;
  border-radius: 14px;
}

.empty-icon {
  width: 70px;
  height: 70px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 22px;
  background: #e8eee9;
  color: #1f3a30;
  border-radius: 50%;
  font-size: 26px;
}

.reservations-empty h2 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 29px;
  margin: 12px 0;
}

.reservations-empty p {
  max-width: 450px;
  margin: 0 auto 25px;
  color: #6f756f;
  font-size: 14px;
  line-height: 1.8;
}

.browse-button {
  display: inline-block;
  background: #1f3a30;
  color: #ffffff !important;
  padding: 12px 20px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  text-decoration: none !important;
}

.browse-button:hover {
  background: #162a22;
}

@media (max-width: 600px) {
  .my-reservations-page {
    padding: 35px 15px 50px;
  }

  .reservations-heading h1 {
    font-size: 32px;
  }

  .reservation-dates {
    gap: 15px;
  }

  .reservation-top,
  .reservation-bottom {
    align-items: flex-start;
    flex-direction: column;
  }
}

sp_widget.script:
(function() {
    data.reservations = [];

    var gr = new GlideRecordSecure('x_2206701_hotel_0_scheduled_reservations');
    gr.addQuery('registered_user', gs.getUserID());
    gr.orderByDesc('sys_created_on');
    gr.query();

    while (gr.next()) {
        data.reservations.push({
            sys_id: gr.getUniqueValue(),
            number: gr.getDisplayValue('number'),
            status: gr.getDisplayValue('reservation_status'),
            room: gr.getDisplayValue('room'),
            check_in: gr.getDisplayValue('check_in_date'),
            check_out: gr.getDisplayValue('check_out_date'),
            adults: gr.getDisplayValue('number_of_adults'),
            children: gr.getDisplayValue('number_of_children'),
            days: gr.getDisplayValue('number_of_days'),
            total: gr.getDisplayValue('total_payment'),
            guest_name: gr.getDisplayValue('guest_name'),
            guest_email: gr.getDisplayValue('guest_email')
        });
    }
})();
